      console.log(f.t.toFixed(3), "pos:", f.pos.x.toFixed(4), f.pos.y.toFixed(4), f.pos.z.toFixed(4), "att:", f.att.roll.toFixed(3), f.att.pitch.toFixed(3), "gate:", f.gateIndex);
    }
