      };

      const cmdRoll = solveAxis('roll', cmdTauRoll);
      const cmdPitch = solveAxis('pitch', cmdTauPitch);
      const cmdYawRate = clamp(rates.yaw + cmdTauYaw / (8 * inertia), -2, 2);

      lastAction = {
        thrust: cmdThrust,
        roll: cmdRoll,
        pitch: cmdPitch,
        yawRate: cmdYawRate,
      };
      return lastAction;
    },
  };
}

